$validate=static function()use($wpdb,$t,$cases,$owned,$zoneId):array{$o=$owned();z4dAssert($o['user'] instanceof WP_User&&$o['user']->roles===[ZonalAdminRole::ROLE]&&$o['user']->display_name==='Administrador Zonal — Capacitación','Cuenta zonal invalida.');$role=get_role(ZonalAdminRole::ROLE);z4dAssert($role instanceof WP_Role,'Rol ausente.');$caps=array_keys(array_filter($role->capabilities));sort($caps);$expected=['read',ZonalAdminRole::CAPABILITY_READ,ZonalAdminRole::CAPABILITY_DECIDE];sort($expected);z4dAssert($caps===$expected,'Capabilities no exactas.');$assignment=$wpdb->get_results($wpdb->prepare("SELECT * FROM {$t['assign']} WHERE user_id=%d ORDER BY id",$o['user']->ID),ARRAY_A);z4dAssert(count($assignment)===1&&(int)$assignment[0]['service_zone_id']===$zoneId,'Asignacion no exacta.');foreach($cases as $key=>$case){z4dAssert($o['users'][$key] instanceof WP_User&&$o['users'][$key]->roles===['veciahorra_minimarket'],"Usuario {$key} invalido.");$s=$o['stores'][$key];z4dAssert(is_array($s)&&$s['business_name']===$case['name']&&$s['status']==='pending'&&$s['onboarding_status']==='complete'&&$s['approved_at']===null,"Store {$key} invalido.");z4dAssert(count($o['relations'][$key])===1&&(int)$o['relations'][$key][0]['zone_id']===$zoneId,"Relacion {$key} invalida.");$id=(int)$s['id'];z4dAssert((int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$t['history']} WHERE store_id=%d",$id))===0,"Historial {$key} no vacio.");z4dAssert((int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$t['inventory']} WHERE minimarket_id=%d",$id))===0,"Inventory {$key} no vacio.");z4dAssert((int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$t['orders']} WHERE minimarket_id=%d",$id))===0,"Orders {$key} no vacio.");}return $o;};
