scribio handoff.');}catch(Throwable $e){foreach($createdStores as $sid){$wpdb->delete($t['zones'],['store_id'=>$sid]);$wpdb->delete($t['stores'],['id'=>$sid]);}if(isset($zonalId)&&is_int($zonalId))$wpdb->delete($t['assign'],['user_id'=>$zonalId]);foreach(array_reverse($createdUsers) as $id)wp_delete_user($id);throw $e;}}$validate();echo "ZONAL_ADMIN_TRAINING_INSTALL=PASS idempotence=PASS\n";
}elseif($op==='validate'){$o=$validate();echo 'ZONAL_ADMIN_TRAINING_VALIDATE=PASS user_id='.$o['user']->ID.' store_ids='.implode(',',array_column($o['stores'],'id'))."\n";
}elseif($op==='reset'){$o=$owned();z4dAssert($o['user'] instanceof WP_User,'Dataset ausente.');foreach($o['stores'] as $s){z4dAssert(is_array($s),'Store ausente.');$wpdb->delete($t['history'],['store_id'=>(int)$s['id']]);z4dAssert($wpdb->update($t['stores'],['status'=>'pending','onboarding_status'=>'complete','approved_at'=>null,'updated_at'=>current_time('mysql')],['id'=>(int)$s['id']])!==false,'Reset fallo.');}$validate();echo "ZONAL_ADMIN_TRAINING_RESET=PASS\n";
}else{$o=$owned();foreach($o['stores'] as $s)if($s){$wpdb->delete($t['history'],['store_id'=>(int)$s['id']]);$wpdb->delete($t['zones'],['store_id'=>(int)$s['id']]);$wpdb->delete($t['stores'],['id'=>(int)$s['id']]);}if($o['user'])$wpdb->delete($t['assign'],['user_id'=>$o['user']->ID]);foreach(array_merge([$o['user']],array_values($o['users'])) as $u)if($u instanceof WP_User)wp_delete_user($u->ID);echo "ZONAL_ADMIN_TRAINING_REMOVE=PASS\n";}
